UPDATE clinlims.menu
SET action_url = '/ResultValidation' || COALESCE('?testSectionId=' || (
    SELECT id FROM clinlims.test_section WHERE name = 'Immunology' AND is_active = 'Y'
), '')
WHERE element_id = 'menu_resultvalidation_immunology';

